glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 v_color;
out vec2 v_nodeUV;
layout(std140) uniform TUNNEL {
  float u_width;
  float u_height;
  float u_brightness;
  float u_minLimit;
  float u_contrastScale;
  float u_vignettePower;
  float u_vignetteScale;
  float u_numLoops;
  float u_flowRotation;
  float u_flowVelocity;
  float u_flowIntensity;
  float u_diagonalBrightness;
  float u_uvRotation;
  float u_swirlRotation;
  float u_stabilization;
  float u_opacity;
};
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  pos = cc_matViewProj * pos;
  v_nodeUV = a_texCoord;
  v_color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 v_color;
in vec2 v_nodeUV;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform TUNNEL {
  float u_width;
  float u_height;
  float u_brightness;
  float u_minLimit;
  float u_contrastScale;
  float u_vignettePower;
  float u_vignetteScale;
  float u_numLoops;
  float u_flowRotation;
  float u_flowVelocity;
  float u_flowIntensity;
  float u_diagonalBrightness;
  float u_uvRotation;
  float u_swirlRotation;
  float u_stabilization;
  float u_opacity;
};
vec4 frag () {
  float t = mod(cc_time.x, 30.0);
  float aspect = u_width / u_height;
  vec2 mappedUV = vec2(v_nodeUV.x / max(aspect, 0.001), v_nodeUV.y);
  vec2 coord = (mappedUV - 0.5) * 2.0;
  vec2 u = 0.2 * vec2(coord.x * aspect, coord.y);
  float rotation_rad = radians(u_uvRotation);
  vec2 col1 = vec2(cos(rotation_rad), sin(rotation_rad));
  vec2 col2 = vec2(-sin(rotation_rad), cos(rotation_rad));
  mat2 rotMat = mat2(col1, col2);
  u = u * rotMat;
  vec4 z = vec4(1.0, 2.0, 3.0, 0.0);
  vec4 o = z;
  vec2 v;
  float a = 0.5;
  vec2 flowDir = vec2(cos(radians(u_flowRotation)), sin(radians(u_flowRotation)));
  float swirlRad = radians(u_swirlRotation);
  vec4 lightParams = vec4(0.0, 11.0 * cos(swirlRad), 33.0 * sin(swirlRad), 0.0);
  for (float i = 0.0; i < 14.0; ++i) {
      if (i >= u_numLoops) break;
      vec4 mVec = cos(vec4(i + 0.02 * t) - lightParams);
      mat2 m = mat2(mVec.xy, mVec.zw);
      float denom = max(0.001, 0.5 - dot(u, u));
      float flowOffset = dot(flowDir, u.yx) * u_flowIntensity;
      vec2 diagDir = u.yx / max(length(u.yx), 0.001);
      float diagMask = pow(abs(dot(flowDir, diagDir)), 4.0);
      float colorScale = mix(1.0, u_diagonalBrightness, diagMask);
      o += (1.0 + cos(z + t)) / max(u_stabilization, length((1.0 + i * dot(u, u)) * sin(1.5 * u / denom - vec2(flowOffset) + vec2(t * u_flowVelocity)))) * colorScale;
      v = cos(vec2(++t) - 7.0 * u * pow(a += 0.03, i));
      vec2 tanhInputVec = 40.0 * dot(u * m, u) * cos(100.0 * u.yx + vec2(t));
      vec2 clampedTanhInput = clamp(tanhInputVec, -20.0, 20.0);
      vec2 tanhResultVec = (exp(2.0 * clampedTanhInput) - 1.0) / (exp(2.0 * clampedTanhInput) + 1.0);
      float oExpArg = dot(o, o) * 0.01;
      u += tanhResultVec * 0.005 + 0.2 * a * u + vec2(cos(4.0 / exp(min(oExpArg, 80.0)) + t) / 300.0);
  }
  o = u_brightness / (min(o, u_minLimit) + u_contrastScale / max(abs(o), 0.001));
  float vignette = 1.0 - pow(length(u) * u_vignetteScale, u_vignettePower);
  vignette = clamp(vignette, 0.0, 1.0);
  vec4 color = vec4(o.rgb, vignette * u_opacity);
  return color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

